// ╔══════════════════════════════════════════════╗
// ║   VALIDATE & SANITIZE — Zone 1              ║
// ╚══════════════════════════════════════════════╝
try {
  // Support both direct JSON and webhook body formats
  const raw = $input.first().json;
  const d = raw.body || raw;

  // ── Required field check ──
  const required = ['patientId', 'patientName', 'age'];
  const missing = required.filter(f => d[f] === undefined || d[f] === null || d[f] === '');
  if (missing.length > 0) {
    throw new Error('VALIDATION_ERROR: Missing required fields: ' + missing.join(', '));
  }

  // ── Age validation ──
  const age = Number(d.age);
  if (isNaN(age) || age < 0 || age > 150) {
    throw new Error('VALIDATION_ERROR: Age must be a number between 0 and 150. Got: ' + d.age);
  }

  // ── Patient ID format ──
  const patientId = String(d.patientId).trim();
  if (patientId.length < 2 || patientId.length > 50) {
    throw new Error('VALIDATION_ERROR: patientId must be 2-50 characters');
  }

  // ── Generate processing ID ──
  const processingId = 'PR-' + Date.now() + '-' + Math.random().toString(36).substr(2, 6).toUpperCase();

  // ── Sanitize vitals ──
  const vitals = {
    heartRate:       d.vitals?.heartRate       ?? null,
    bloodPressure:   d.vitals?.bloodPressure   ?? null,
    oxygenLevel:     d.vitals?.oxygenLevel     ?? null,
    temperature:     d.vitals?.temperature     ?? null,
    respiratoryRate: d.vitals?.respiratoryRate ?? null,
    glucoseLevel:    d.vitals?.glucoseLevel    ?? null
  };

  return [{
    json: {
      patientId,
      patientName:        String(d.patientName).trim(),
      age,
      gender:             d.gender            || 'Not Specified',
      ward:               d.ward              || 'General Ward',
      attendingDoctor:    d.attendingDoctor   || 'On-Call Physician',
      vitals,
      symptoms:           Array.isArray(d.symptoms)            ? d.symptoms            : [],
      medicalHistory:     Array.isArray(d.medicalHistory)      ? d.medicalHistory      : [],
      currentMedications: Array.isArray(d.currentMedications)  ? d.currentMedications  : [],
      labResults:         d.labResults || {},
      notifyEmails:       d.notifyEmails || d.notifyEmail || 'alerts@hospital.com',
      processingId,
      receivedAt:         new Date().toISOString(),
      workflowVersion:    '2.0.0',
      validationStatus:   'PASSED'
    }
  }];
} catch (err) {
  // Re-throw with structured prefix so error handler can categorise
  const msg = err.message.startsWith('VALIDATION_ERROR:') ? err.message : 'VALIDATION_ERROR: ' + err.message;
  throw new Error(msg);
}

// ╔══════════════════════════════════════════════╗
// ║   ENRICH WITH CLINICAL CONTEXT — Zone 2     ║
// ╚══════════════════════════════════════════════╝
const d = $input.first().json;

// Ward-to-department escalation map
const WARD_MAP = {
  'ICU':            { dept: 'Intensive Care',         escalationLevel: 1, primaryContact: 'icu-team@hospital.com' },
  'CCU':            { dept: 'Cardiac Care',            escalationLevel: 1, primaryContact: 'ccu-team@hospital.com' },
  'Emergency':      { dept: 'Emergency Medicine',      escalationLevel: 1, primaryContact: 'er-team@hospital.com' },
  'Cardiology':     { dept: 'Cardiology',              escalationLevel: 2, primaryContact: 'cardiology@hospital.com' },
  'Neurology':      { dept: 'Neurology',               escalationLevel: 2, primaryContact: 'neuro@hospital.com' },
  'General Ward':   { dept: 'General Medicine',        escalationLevel: 3, primaryContact: 'general@hospital.com' },
  'Surgical':       { dept: 'Surgery',                 escalationLevel: 2, primaryContact: 'surgery@hospital.com' },
  'Pediatric':      { dept: 'Pediatrics',              escalationLevel: 2, primaryContact: 'peds@hospital.com' },
};

const wardInfo = WARD_MAP[d.ward] || { dept: 'General Medicine', escalationLevel: 3, primaryContact: 'general@hospital.com' };

// Risk-factor flags from medical history
const HIGH_RISK_CONDITIONS = ['diabetes', 'hypertension', 'heart disease', 'COPD', 'renal failure', 'cancer', 'immunocompromised'];
const flaggedConditions = (d.medicalHistory || []).filter(h =>
  HIGH_RISK_CONDITIONS.some(c => h.toLowerCase().includes(c.toLowerCase()))
);

// Age-based risk multiplier
let ageRiskCategory = 'Standard';
if (d.age >= 75) ageRiskCategory = 'Geriatric High Risk';
else if (d.age >= 65) ageRiskCategory = 'Elderly';
else if (d.age <= 12) ageRiskCategory = 'Pediatric';

// Critical vital thresholds check
const vitals = d.vitals || {};
const criticalFlags = [];
if (vitals.oxygenLevel && vitals.oxygenLevel < 90)  criticalFlags.push('SpO2 critically low (' + vitals.oxygenLevel + '%)');
if (vitals.heartRate   && vitals.heartRate > 130)   criticalFlags.push('Tachycardia (' + vitals.heartRate + ' bpm)');
if (vitals.heartRate   && vitals.heartRate < 40)    criticalFlags.push('Bradycardia (' + vitals.heartRate + ' bpm)');
if (vitals.temperature && vitals.temperature > 39.5) criticalFlags.push('High fever (' + vitals.temperature + '°C)');
if (vitals.temperature && vitals.temperature < 35.0) criticalFlags.push('Hypothermia (' + vitals.temperature + '°C)');

return [{
  json: {
    ...d,
    // Clinical enrichment
    departmentInfo:     wardInfo,
    escalationLevel:    wardInfo.escalationLevel,
    departmentContact:  wardInfo.primaryContact,
    flaggedConditions,
    ageRiskCategory,
    criticalVitalFlags: criticalFlags,
    preAssessmentRisk:  criticalFlags.length >= 2 ? 'HIGH_SUSPICION' : (criticalFlags.length === 1 ? 'ELEVATED' : 'NORMAL'),
    // Merge notification targets
    notifyEmails: [d.notifyEmails, wardInfo.primaryContact].filter(Boolean).join(', '),
    enrichedAt: new Date().toISOString()
  }
}];

// ╔══ HANDLE LOW ══╗
const d = $input.first().json;

return [{
  json: {
    ...d,
    alertType:      'LOW',
    priority:       4,
    emailSubject:   `[🟢 LOW RISK] ${d.patientId} – ${d.patientName} | Stable | ${d.processingId}`,
    emailBody:      `Patient ${d.patientName} assessed as LOW RISK (score: ${d.riskScore}/100). Standard monitoring protocol appropriate.`,
    slackMessage:   null,
    requiresEmail:  false,
    requiresSlack:  false,
    slaMinutes:     null
  }
}];

// ╔══ HANDLE ERROR ══╗
const d = $input.first().json;

const emailSubject = `[⚫ ERROR] AI Assessment Failed – ${d.patientId || 'Unknown'} | Manual Review Required`;

const emailBody = [
  '╔══════════════════════════════════════════════════╗',
  '║       ⚫  AI ASSESSMENT ERROR — ACTION NEEDED    ║',
  '╚══════════════════════════════════════════════════╝',
  '',
  `  Patient ID:   ${d.patientId || 'Unknown'}`,
  `  Patient Name: ${d.patientName || 'Unknown'}`,
  `  Ward:         ${d.ward || 'Unknown'}`,
  '',
  '  ⚠️  The AI risk assessment could not be completed.',
  '  IMMEDIATE manual clinical review is required.',
  '',
  `  Error Details: ${d.parseError || 'Unknown error'}`,
  `  Processing ID: ${d.processingId || 'N/A'}`,
  `  Time:          ${new Date().toISOString()}`,
  '══════════════════════════════════════════════════',
].join('\n');

return [{
  json: {
    ...d,
    alertType:      'ERROR',
    priority:       1,
    emailSubject,
    emailBody,
    slackMessage:   null,
    requiresEmail:  true,
    requiresSlack:  false,
    slaMinutes:     30
  }
}];

// ╔══════════════════════════════════════════════╗
// ║              AUDIT LOGGER                    ║
// ╚══════════════════════════════════════════════╝

const d =$('Merge').first().json;

// AI assessment data
const ai = d.output || {};

// Calculate processing time
const processingMs =
  d.receivedAt
    ? (new Date().getTime() - new Date(d.receivedAt).getTime())
    : null;

// Structured audit record
const auditRecord = {

  // ==========================================
  // IDENTIFIERS
  // ==========================================
  processingId: d.processingId,
  patientId: d.patientId,
  patientName: d.patientName,
  ward: d.ward,
  department: d.departmentInfo?.dept || null,

  // ==========================================
  // RISK ASSESSMENT
  // ==========================================
  riskLevel: ai.riskLevel,
  riskScore: ai.riskScore,
  confidence: ai.confidence,

  alertType: d.alertType || ai.riskLevel,

  // ==========================================
  // TIMESTAMPS
  // ==========================================
  receivedAt: d.receivedAt,
  enrichedAt: d.enrichedAt,
  auditLoggedAt: new Date().toISOString(),
  processingMs,

  // ==========================================
  // CLINICAL SUMMARY
  // ==========================================
  ageRiskCategory: d.ageRiskCategory,
  preAssessmentRisk: d.preAssessmentRisk,

  primaryConcerns:
    (ai.primaryConcerns || [])
      .slice(0, 3)
      .join(' | '),

  topAction:
    (ai.immediateActions || [])[0] || null,

  criticalVitalFlags:
    (d.criticalVitalFlags || [])
      .join(' | '),

  symptoms:
    (d.symptoms || [])
      .join(' | '),

  // ==========================================
  // NOTIFICATION STATUS
  // ==========================================
  emailSent: d.requiresEmail || false,
  slackSent: d.requiresSlack || false,

  escalationLevel: d.escalationLevel,
  slaMinutes: d.slaMinutes,

  // ==========================================
  // WORKFLOW
  // ==========================================
  workflowVersion: d.workflowVersion,
  validationStatus: d.validationStatus,

  // ==========================================
  // ERROR HANDLING
  // ==========================================
  parseError: d.parseError || null
};

// Store last 100 audits in workflow memory
const staticData = $getWorkflowStaticData('global');

if (!staticData.auditLog) {
  staticData.auditLog = [];
}

staticData.auditLog.unshift(auditRecord);

if (staticData.auditLog.length > 100) {
  staticData.auditLog = staticData.auditLog.slice(0, 100);
}

// Return original payload + audit info
return [
  {
    json: {
      ...d,
      auditRecord,
      auditLogged: true
    }
  }
];

// ╔══════════════════════════════════════════════╗
// ║   FORMAT ERROR REPORT — Zone 7              ║
// ╚══════════════════════════════════════════════╝
const err = $input.first().json;

const subject = `[🔴 WORKFLOW ERROR] Health Risk Monitor — ${err.execution?.id || 'Unknown Execution'}`;

const body = [
  '╔══════════════════════════════════════════════════╗',
  '║    🔴  WORKFLOW ERROR — IMMEDIATE ATTENTION     ║',
  '╚══════════════════════════════════════════════════╝',
  '',
  `  Workflow:      ${err.workflow?.name || 'AI Patient Risk Monitoring System'}`,
  `  Execution ID:  ${err.execution?.id || 'N/A'}`,
  `  Failed Node:   ${err.execution?.lastNodeExecuted || 'Unknown'}`,
  `  Error:         ${err.execution?.error?.message || 'Unknown error'}`,
  `  Stack:         ${err.execution?.error?.stack?.substring(0, 300) || 'N/A'}`,
  `  Timestamp:     ${new Date().toISOString()}`,
  '',
  '  ⚠️  A patient risk assessment workflow has failed.',
  '  Manual clinical review of any pending patients is required.',
  '',
  '  Please check the n8n execution logs for full details.',
  '══════════════════════════════════════════════════',
].join('\n');

return [{
  json: {
    errorReportSubject: subject,
    errorReportBody:    body,
    errorContext:       err,
    reportedAt:         new Date().toISOString()
  }
}];

// Handle OpenAI API hard failure (all 3 retries exhausted)
const d = $input.first().json;
const errMsg = d.message || d.error?.message || 'OpenAI API unreachable after 3 retries';
return [{
  json: {
    ...d,
    riskLevel: 'ERROR',
    riskScore: 0,
    confidence: 0,
    primaryConcerns: ['AI assessment system unreachable'],
    clinicalFindings: [],
    immediateActions: ['URGENT: Manual clinical review required immediately', 'Contact on-call physician for ' + (d.patientName || 'patient')],
    monitoringParameters: [],
    estimatedTimeToIntervention: 'immediate',
    clinicalNarrative: 'Automated AI assessment failed (API error). Immediate manual review required.',
    flaggedVitals: [],
    differentialConsiderations: [],
    recommendedSpecialties: [],
    medicationAlerts: [],
    assessedAt: new Date().toISOString(),
    parseError: 'OpenAI API Error: ' + errMsg,
    aiModelUsed: 'N/A - API failure',
    openAiTokensUsed: 0
  }
}];

const sd = $getWorkflowStaticData('global');

const patientId =
  $json.body?.patientId ??
  $json.patientId ??
  'unknown';

const key = `rl_${patientId}`;

const now = Date.now();
const tenMinutes = 10 * 60 * 1000;

let allowed = true;

if (sd[key] && (now - sd[key]) < tenMinutes) {
  allowed = false;
}

sd[key] = now;

return [{
  json: {
    ...$json,
    allowed
  }
}];
